  (function(){
    // Search bar toggle
    var btn = document.getElementById('mag-search-btn');
    var bar = document.getElementById('mag-search-bar');
    if (btn && bar) {
      btn.addEventListener('click', function(){ bar.classList.toggle('d-none'); });
    }

    // Ticker: carrega posts recentes
    var ticker = document.getElementById('mag-ticker-items');
    if (ticker) {
      fetch('/feeds/posts/default?alt=json&max-results=8&orderby=published')
        .then(function(r){ return r.ok ? r.json() : null; })
        .then(function(data){
          if (!data || !data.feed || !data.feed.entry) return;
          ticker.innerHTML = data.feed.entry.map(function(e){
            var lnk = (e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
            var url = lnk ? lnk.href : '#';
            var t = (e.title||{}).$t || '';
            return '<a class="text-white text-decoration-none" href="'+url+'">'+t+'</a>';
          }).join('<span class="mx-3 text-white-50" aria-hidden="true">·</span>');
        })
        .catch(function(){
          var bar2 = ticker.closest && ticker.closest('.mag-ticker-bar');
          if (bar2) bar2.style.display = 'none';
        });
    }

    // Trending: carrega posts recentes no sidebar
    var trendingList = document.getElementById('mag-trending-list');
    if (trendingList) {
      fetch('/feeds/posts/default?alt=json&max-results=6&orderby=published')
        .then(function(r){ return r.ok ? r.json() : null; })
        .then(function(data){
          if (!data || !data.feed || !data.feed.entry) return;
          trendingList.innerHTML = data.feed.entry.slice(0,6).map(function(e){
            var lnk = (e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
            var url = lnk ? lnk.href : '#';
            var t = (e.title||{}).$t || '';
            var d = (e.published||{}).$t ? new Date(e.published.$t).toLocaleDateString('pt-BR') : '';
            return '<li><div><a href="'+url+'">'+t+'</a>'
              +'<div class="small text-muted mt-1"><i class="bi bi-clock me-1"></i>'+d+'</div></div></li>';
          }).join('');
        })
        .catch(function(){
          var w = trendingList.closest && trendingList.closest('#mag-sidebar-trending');
          if (w) w.style.display = 'none';
        });
    }
  })();
  //





  //
  (function(){
    var grid = document.getElementById('sl-related-ready');
    if (!grid) return;
    function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
    var label      = (document.getElementById('sl-post-label')||{}).textContent.trim();
    var currentUrl = (document.getElementById('sl-post-url')  ||{}).textContent.trim();
    if (!label) { var rp=grid.closest('.sl-related-posts'); if(rp) rp.style.display='none'; return; }
    fetch('/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results=4')
      .then(function(r){ if(!r.ok) throw 0; return r.json(); })
      .then(function(data){
        var entries=(data.feed.entry||[]).filter(function(e){
          var l=(e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
          return l && l.href!==currentUrl;
        }).slice(0,3);
        if(!entries.length){ var rp2=grid.closest('.sl-related-posts'); if(rp2) rp2.style.display='none'; return; }
        grid.innerHTML=entries.map(function(e){
          var l=(e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
          var url=esc(l?l.href:'#');
          var title=esc((e.title||{}).$t||'');
          var cat=esc(((e.category||[])[0]||{}).term||'');
          var raw=(e.media$thumbnail||{}).url||'';
          var thumb=esc(raw?raw.replace(/\/s[\d]+-c(\/|$)/,'/w400-h225-c/'):'[[PLACEHOLDER_IMG]]');
          var date=(e.published||{}).$t?new Date(e.published.$t).toLocaleDateString('pt-BR'):'';
          return '<div class="col"><article class="news-card d-flex flex-column h-100">'
            +'<a href="'+url+'"><img src="'+thumb+'" alt="'+title+'" class="w-100" style="object-fit:cover;aspect-ratio:16/9;"/></a>'
            +'<div class="p-3 d-flex flex-column flex-grow-1 border-top">'
            +(cat?'<span class="text-primary fw-bold small text-uppercase mb-1">'+cat+'</span>':'')
            +'<h3 class="h6 fw-bold mb-2"><a class="text-body text-decoration-none" href="'+url+'">'+title+'</a></h3>'
            +'<div class="mt-auto small text-muted"><i class="bi bi-clock me-1"></i>'+esc(date)+'</div>'
            +'</div></article></div>';
        }).join('');
      })
      .catch(function(){ var rp3=grid.closest('.sl-related-posts'); if(rp3) rp3.style.display='none'; });
  })();
